//! Host proof of the OTA decision (BOUCHAUD_OTA_V1): system/update-core/src/ota.rs.
//!
//!   rustc --edition 2021 --test tools/update/test_ota.rs -o /tmp/tota && /tmp/tota
//!
//! Keys are generated by OpenSSL at test time (never stored). Each refusal
//! is a negative witness: a hostile or broken source gets NOTHING offered.

#![allow(dead_code)]

#[path = "../../system/update-core/src/ab.rs"]
mod ab;
#[path = "../../system/update-core/src/anti_retour.rs"]
mod anti_retour;
#[path = "../../system/update-core/src/ed25519.rs"]
mod ed25519;
#[path = "../../system/update-core/src/manifeste.rs"]
mod manifeste;
#[path = "../../system/update-core/src/ota.rs"]
mod ota;

use anti_retour::{Lecture, Registre};
use manifeste::CleDeConfiance;
use ota::{decide, Decision, Refus};
use std::process::Command;

struct Cle { dir: std::path::PathBuf, publique: [u8; 32] }

fn cle(nom: &str) -> Cle {
    let n = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().subsec_nanos();
    let dir = std::env::temp_dir().join(format!("bo-ota-{}-{}-{nom}", std::process::id(), n));
    std::fs::create_dir_all(&dir).unwrap();
    let k = dir.join("k.pem");
    assert!(Command::new("openssl").args(["genpkey", "-algorithm", "ed25519", "-out"]).arg(&k).status().unwrap().success());
    let der = Command::new("openssl").args(["pkey", "-pubout", "-outform", "DER", "-in"]).arg(&k).output().unwrap().stdout;
    let mut p = [0u8; 32];
    p.copy_from_slice(&der[der.len() - 32..]);
    Cle { publique: p, dir }
}

fn signe(c: &Cle, m: &[u8]) -> [u8; 64] {
    let (mf, sf) = (c.dir.join("m"), c.dir.join("s"));
    std::fs::write(&mf, m).unwrap();
    assert!(Command::new("openssl").args(["pkeyutl", "-sign", "-rawin", "-inkey"]).arg(c.dir.join("k.pem"))
        .arg("-in").arg(&mf).arg("-out").arg(&sf).status().unwrap().success());
    let mut s = [0u8; 64];
    s.copy_from_slice(&std::fs::read(&sf).unwrap());
    s
}

const H: &str = "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff";

fn v2(seq: u64, materiel: &str) -> Vec<u8> {
    format!("bouchaud-manifeste-v2\nversion=2026.11.12-{seq}\nsequence={seq}\nmateriel={materiel}\nimage_sha256={H}\nimage_octets=97517568\nessais=3\n").into_bytes()
}

fn confiance(c: &Cle) -> [CleDeConfiance; 1] {
    [CleDeConfiance { nom: "release-test", publique: c.publique, developpement: false }]
}

fn plancher(p: u64) -> Lecture {
    Lecture::Valide(Registre { sequence: 3, plancher: p, slots: [p, 0] })
}

#[test]
fn release_plus_recente_disponible() {
    let c = cle("a");
    let t = v2(1002, "x86_64-uefi");
    match decide(&t, &signe(&c, &t), &confiance(&c), plancher(1001), 1001, "x86_64-uefi") {
        Ok(Decision::Disponible(m)) => {
            assert_eq!(m.sequence, 1002);
            assert_eq!(m.octets, 97517568);
            assert_eq!(m.version(), "2026.11.12-1002");
        }
        autre => panic!("{autre:?}"),
    }
}

#[test]
fn meme_release_a_jour() {
    let c = cle("b");
    let t = v2(1001, "x86_64-uefi");
    assert_eq!(decide(&t, &signe(&c, &t), &confiance(&c), plancher(1001), 1001, "x86_64-uefi"),
               Ok(Decision::AJour { sequence: 1001 }));
    // Running release unknown (0) but the floor says 1001: still up to date.
    assert_eq!(decide(&t, &signe(&c, &t), &confiance(&c), plancher(1001), 0, "x86_64-uefi"),
               Ok(Decision::AJour { sequence: 1001 }));
}

#[test]
fn installation_neuve_sans_plancher() {
    let c = cle("c");
    let t = v2(5, "x86_64-uefi");
    assert!(matches!(decide(&t, &signe(&c, &t), &confiance(&c), Lecture::Neuf, 0, "x86_64-uefi"),
                     Ok(Decision::Disponible(_))));
}

#[test]
fn temoins_de_refus() {
    let c = cle("d");
    let autre = cle("e");
    let t = v2(1002, "x86_64-uefi");
    let s = signe(&c, &t);
    let k = confiance(&c);
    let x = "x86_64-uefi";
    // Fail closed: no trusted key (a production build without a key).
    assert_eq!(decide(&t, &s, &[], plancher(1001), 1001, x), Err(Refus::AucuneCleDeConfiance));
    // Signed by someone else.
    assert_eq!(decide(&t, &signe(&autre, &t), &k, plancher(1001), 1001, x), Err(Refus::SignatureNonFiable));
    // Any altered byte or bit of the signature.
    for i in [0usize, 20, t.len() - 1] {
        let mut u = t.clone();
        u[i] ^= 1;
        assert_eq!(decide(&u, &s, &k, plancher(1001), 1001, x), Err(Refus::SignatureNonFiable), "octet {i}");
    }
    let mut s2 = s;
    s2[63] ^= 0x80;
    assert_eq!(decide(&t, &s2, &k, plancher(1001), 1001, x), Err(Refus::SignatureNonFiable));
    // Signed downgrade (an old, possibly vulnerable release).
    let vieux = v2(999, x);
    assert_eq!(decide(&vieux, &signe(&c, &vieux), &k, plancher(1001), 1001, x), Err(Refus::Retrograde));
    // Signed for another hardware family.
    let arm = v2(1002, "arm64-uefi");
    assert_eq!(decide(&arm, &signe(&c, &arm), &k, plancher(1001), 1001, x), Err(Refus::MaterielIncompatible));
    // Signed v1 (no sequence): never offered.
    let v1 = format!("bouchaud-manifeste-v1\nversion=x\nimage_sha256={H}\nimage_octets=1\nessais=3\n").into_bytes();
    assert_eq!(decide(&v1, &signe(&c, &v1), &k, Lecture::Neuf, 0, x), Err(Refus::SansSequence));
    // Signed but not canonical.
    let mut nc = t.clone();
    nc.extend_from_slice(b"x=1\n");
    assert_eq!(decide(&nc, &signe(&c, &nc), &k, plancher(1001), 1001, x), Err(Refus::ManifesteNonCanonique));
    // Unreadable anti-rollback record.
    assert_eq!(decide(&t, &s, &k, Lecture::Illisible, 1001, x), Err(Refus::RegistreIllisible));
}
